function projectsToMermaidGantt(projects, title = "Project Matrix Dashboard") {
  const lines = [
    "gantt",
    "    dateFormat YYYY-MM-DD",
    `    title ${title}`,
    "    excludes weekends"
  ];
  for (const project of projects) {
    lines.push(`    section ${project.name}`);
    for (const task of project.tasks) {
      const modifiers = [];
      if (task.status === "done" /* DONE */) {
        modifiers.push("done");
      } else if (task.status === "in-progress" /* IN_PROGRESS */) {
        modifiers.push("active");
      } else if (task.status === "blocked" /* BLOCKED */) {
        modifiers.push("crit");
      }
      const safeId = (task.id || `task_${Math.random().toString(36).substring(2, 7)}`).replace(/[^a-zA-Z0-9_-]/g, "_");
      modifiers.push(safeId);
      const modStr = modifiers.join(", ");
      lines.push(`    ${task.title} :${modStr}, ${task.startDate}, ${task.endDate}`);
    }
  }
  return lines.join("\n");
}

